<?php if(!$transferRows):?><p class="butchery-empty">Aucun transfert dans cette sélection.</p><?php else:?>
<table class="enterprise-table" <?=$withFilters?'data-butchery-history="inter-site"':''?> data-status-options="<?=e(json_encode($statusOptions,JSON_UNESCAPED_UNICODE))?>" data-search-placeholder="Référence, site, créateur…"><thead><tr><th>Référence / date</th><th>Trajet</th><th>Demandés</th><th>Expédiés</th><th>Reçus</th><th>Statut</th><th>Actions</th></tr></thead><tbody>
<?php foreach($transferRows as $row):$sum=$totals[$row['id']];?>
<tr data-status="<?=e($row['status'])?>" data-type="<?=e($row['transfer_type'])?>" data-date="<?=e(substr($row['requested_at'],0,10))?>"><td><strong><?=e($row['transfer_number'])?></strong><small><?=e($transferDate($row['requested_at']))?> · <?=e($row['creator_name'])?></small></td><td><strong><?=e($row['source_code'].' → '.$row['destination_code'])?></strong><small><?=$row['transfer_type']==='internal'?'Interne':'Inter-site'?></small></td><?php foreach(['requested_bags','shipped_bags','received_bags'] as $field):?><td data-order="<?=$sum[$field]?>"><?=e(number_format($sum[$field],0,',',' '))?></td><?php endforeach;?><td><span class="butchery-status <?=in_array($row['status'],['accepted','closed'],true)?'butchery-status-success':''?>"><?=e($transferLabels[$row['status']]??$row['status'])?></span></td><td><div class="table-actions"><button type="button" class="btn-secondary" data-workspace-modal-open="transfer-detail-<?=e($row['id'])?>" aria-label="<?=e('Consulter '.$row['transfer_number'])?>">Détails</button><a class="icon-button" href="<?=e(base_url('transfers/'.$row['id']))?>" aria-label="<?=e('Ouvrir le dossier '.$row['transfer_number'])?>" title="Ouvrir le dossier"><i class="bi bi-arrow-up-right" aria-hidden="true"></i></a></div></td></tr>
<?php endforeach;?></tbody></table>
<?php endif;?>
